#include <reg51.h>

sbit WAVE_OUT = P1^0; // Output pin P1.0

void delay_500us(void) {
    TMOD &= 0xF0;     // Clear Timer 0 mode bits
    TMOD |= 0x01;     // Set Timer 0 in Mode 1 (16-bit timer)

    // 12 MHz crystal: 1 machine cycle = 1 us.
    // Preload = 65536 - 425 = 65111 (0xFE57). The while(TF0==0) polling
    // loop detects the overflow on its 14-cycle iteration, so the half
    // period comes out at ~494 us instead of 500 -> ~1.01 kHz (within 1%).
    TH0 = 0xFE;
    TL0 = 0x57;

    TR0 = 1;          // Start Timer 0
    while (TF0 == 0); // Wait until Timer 0 overflows
    TR0 = 0;          // Stop Timer 0
    TF0 = 0;          // Clear Timer 0 flag
}

void main(void) {
    WAVE_OUT = 0;     // Initialize output
    while (1) {
        WAVE_OUT = ~WAVE_OUT; // Toggle P1.0 pin
        delay_500us();        // Wait 500 microseconds
    }
}
